//! Vulkan drawing (the feature `gpu-draw`): a recorded paint (`gpu_draw::DrawList`) drawn into
//! a window's image, by the Vulkan paths of Windows, X11 and Wayland alike.
//!
//! - The shaders are SPIR-V, compiled from GLSL made of `gpu_draw::SHADING` and the parts here
//!   (`glslc -O`, shaderc 2026.3): users' machines have no compiler. A test compiles them again
//!   and compares.
//! - The quads go up into a buffer read as instanced attributes; glyphs and runs into a kept
//!   cache image, patches and pictures into an image of this part's. Both are B8G8R8A8, as the
//!   window's: no channel is swapped.
//! - GDI's runs blend per channel (dual-source blending) where the device has `dualSrcBlend`;
//!   elsewhere there are none (Linux), or a part with one is drawn by the CPU (`dual`).
//! - Everything is recorded into the caller's command buffer: the caller submits and waits.
use crate::gpu_draw::{DrawList, Quad, SHADING, SIDE};
use crate::layer_vulkan::{
    VkDescriptorImageInfo, VkDescriptorPoolCreateInfo, VkDescriptorPoolSize, VkDescriptorSetAllocateInfo, VkDescriptorSetLayoutBinding, VkDescriptorSetLayoutCreateInfo, VkGraphicsPipelineCreateInfo,
    VkPipelineColorBlendAttachmentState, VkPipelineColorBlendStateCreateInfo, VkPipelineDynamicStateCreateInfo, VkPipelineInputAssemblyStateCreateInfo, VkPipelineLayoutCreateInfo,
    VkPipelineMultisampleStateCreateInfo, VkPipelineRasterizationStateCreateInfo, VkPipelineShaderStageCreateInfo, VkPipelineVertexInputStateCreateInfo, VkPipelineViewportStateCreateInfo,
    VkShaderModuleCreateInfo, VkWriteDescriptorSet,
};
use crate::vk::*;
use std::ffi::{CStr, c_void};
use std::ptr::{null, null_mut};

structures! {
    VkVertexInputBindingDescription { binding: u32, stride: u32, rate: u32, }
    VkVertexInputAttributeDescription { location: u32, binding: u32, format: u32, offset: u32, }
}

functions!(Calls {
    vkCreateImage: fn(Object, *const VkImageCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyImage: fn(Object, Handle, *const c_void);
    vkGetImageMemoryRequirements: fn(Object, Handle, *mut VkMemoryRequirements);
    vkBindImageMemory: fn(Object, Handle, Handle, u64) -> i32;
    vkCreateImageView: fn(Object, *const VkImageViewCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyImageView: fn(Object, Handle, *const c_void);
    vkCreateBuffer: fn(Object, *const VkBufferCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyBuffer: fn(Object, Handle, *const c_void);
    vkGetBufferMemoryRequirements: fn(Object, Handle, *mut VkMemoryRequirements);
    vkBindBufferMemory: fn(Object, Handle, Handle, u64) -> i32;
    vkAllocateMemory: fn(Object, *const VkMemoryAllocateInfo, *const c_void, *mut Handle) -> i32;
    vkFreeMemory: fn(Object, Handle, *const c_void);
    vkMapMemory: fn(Object, Handle, u64, u64, u32, *mut *mut c_void) -> i32;
    vkCreateSampler: fn(Object, *const VkSamplerCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroySampler: fn(Object, Handle, *const c_void);
    vkCreateDescriptorSetLayout: fn(Object, *const VkDescriptorSetLayoutCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyDescriptorSetLayout: fn(Object, Handle, *const c_void);
    vkCreateDescriptorPool: fn(Object, *const VkDescriptorPoolCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyDescriptorPool: fn(Object, Handle, *const c_void);
    vkAllocateDescriptorSets: fn(Object, *const VkDescriptorSetAllocateInfo, *mut Handle) -> i32;
    vkUpdateDescriptorSets: fn(Object, u32, *const VkWriteDescriptorSet, u32, *const c_void);
    vkCreatePipelineLayout: fn(Object, *const VkPipelineLayoutCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyPipelineLayout: fn(Object, Handle, *const c_void);
    vkCreateShaderModule: fn(Object, *const VkShaderModuleCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyShaderModule: fn(Object, Handle, *const c_void);
    vkCreateGraphicsPipelines: fn(Object, Handle, u32, *const VkGraphicsPipelineCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyPipeline: fn(Object, Handle, *const c_void);
    vkCreateRenderPass: fn(Object, *const VkRenderPassCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyRenderPass: fn(Object, Handle, *const c_void);
    vkCreateFramebuffer: fn(Object, *const VkFramebufferCreateInfo, *const c_void, *mut Handle) -> i32;
    vkDestroyFramebuffer: fn(Object, Handle, *const c_void);
    vkCmdPipelineBarrier: fn(Object, u32, u32, u32, u32, *const c_void, u32, *const c_void, u32, *const VkImageMemoryBarrier);
    vkCmdCopyBufferToImage: fn(Object, Handle, Handle, u32, u32, *const VkBufferImageCopy);
    vkCmdBeginRenderPass: fn(Object, *const VkRenderPassBeginInfo, u32);
    vkCmdEndRenderPass: fn(Object);
    vkCmdBindPipeline: fn(Object, u32, Handle);
    vkCmdBindDescriptorSets: fn(Object, u32, Handle, u32, u32, *const Handle, u32, *const u32);
    vkCmdBindVertexBuffers: fn(Object, u32, u32, *const Handle, *const u64);
    vkCmdSetViewport: fn(Object, u32, u32, *const VkViewport);
    vkCmdSetScissor: fn(Object, u32, u32, *const VkRect2D);
    vkCmdDraw: fn(Object, u32, u32, u32, u32);
});

// Copies between images: X11's and Wayland's windows are drawn in an image of their own.
#[cfg(all(unix, not(target_os = "android")))]
functions!(Copying {
    vkCmdCopyImage: fn(Object, Handle, u32, Handle, u32, u32, *const VkImageCopy);
});

/// A buffer of vertices; one copied from.
const USAGE_VERTICES: u32 = 0x80;
const USAGE_COPIED_FROM: u32 = 0x1;
/// Four 32-bit floats (`VK_FORMAT_R32G32B32A32_SFLOAT`).
const FOUR_FLOATS: u32 = 109;
/// Stages reading the textures and the quads.
const STAGE_SHADERS: u32 = 0x4 | 0x8 | STAGE_FRAGMENT_SHADER;

/// Where an image is before drawing and what used it: its layout, access and stage.
#[derive(Clone, Copy, Debug)]
pub(crate) struct Was {
    pub(crate) layout: u32,
    pub(crate) access: u32,
    pub(crate) stage: u32,
}

/// An image the shaders read: it, its memory and its view.
#[derive(Clone, Copy, Debug, Default)]
struct Texture {
    image: Handle,
    memory: Handle,
    view: Handle,
}

/// A buffer the CPU writes: it, its memory, where the CPU sees it, and its size in bytes.
#[derive(Clone, Copy, Debug)]
struct Written {
    buffer: Handle,
    memory: Handle,
    at: *mut u8,
    room: usize,
}

impl Default for Written {
    #[inline]
    fn default() -> Self {
        Written { buffer: 0, memory: 0, at: null_mut(), room: 0 }
    }
}

/// What a device draws with: its functions, the render pass, pipeline and what it reads (the
/// cache and patch images, a sampler, the descriptor set), the buffers the texels and quads go
/// up through, and the framebuffer of the image drawn into last.
pub(crate) struct Pipeline {
    calls: Calls,
    #[cfg(all(unix, not(target_os = "android")))]
    copying: Copying,
    device: Object,
    /// The kinds of memory in the device's own memory, and those the CPU writes: one bit each.
    pub(crate) local: u32,
    writable: u32,
    /// GDI's runs are blended per channel.
    pub(crate) dual: bool,
    pass: Handle,
    set_layout: Handle,
    layout: Handle,
    pipeline: Handle,
    descriptors: Handle,
    set: Handle,
    sampler: Handle,
    textures: [Texture; 2],
    /// The textures have been readied for shaders.
    readied: bool,
    staging: Written,
    quads: Written,
    /// The image drawn into last, its size, its view and framebuffer.
    target: (Handle, [i32; 2], Handle, Handle),
    /// The copies into each texture, kept for their room.
    copies: [Vec<VkBufferImageCopy>; 2],
    /// What draws videos' frames from the decoder's buffers, where the device imports them
    /// (`video_vulkan`).
    #[cfg(all(feature = "video", unix))]
    pub(crate) frames: Option<Box<crate::video_vulkan::Frames>>,
}

// SAFETY: as its device: used by one thread at a time.
unsafe impl Send for Pipeline {}

impl std::fmt::Debug for Pipeline {
    #[inline]
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Pipeline").field("dual", &self.dual).field("staging", &self.staging.room).field("quads", &self.quads.room).finish_non_exhaustive()
    }
}

impl Pipeline {
    /// What `device` draws with, its functions found by `find`, its memory as `memory` says;
    /// with `dual` (the device made with `dualSrcBlend`), GDI's runs blended per channel.
    /// Nothing where any part can't be made.
    pub(crate) fn new(find: &mut dyn FnMut(&CStr) -> *const c_void, device: Object, memory: &VkPhysicalDeviceMemoryProperties, dual: bool) -> Option<Box<Pipeline>> {
        let calls = Calls::load(find).ok()?;
        // Only GDI's runs (Windows) blend per channel.
        let dual = dual && cfg!(windows);
        #[cfg(all(unix, not(target_os = "android")))]
        let copying = Copying::load(find).ok()?;
        let (local, writable) = (kinds(memory, DEVICE_LOCAL), kinds(memory, HOST_VISIBLE_AND_COHERENT));
        let mut made = Box::new(Pipeline {
            calls,
            #[cfg(all(unix, not(target_os = "android")))]
            copying,
            device,
            local,
            writable,
            dual,
            pass: 0,
            set_layout: 0,
            layout: 0,
            pipeline: 0,
            descriptors: 0,
            set: 0,
            sampler: 0,
            textures: [Texture::default(); 2],
            readied: false,
            staging: Written::default(),
            quads: Written::default(),
            target: (0, [0; 2], 0, 0),
            copies: [Vec::new(), Vec::new()],
            #[cfg(all(feature = "video", unix))]
            frames: None,
        });
        let textures = [made.texture()?, made.texture()?];
        made.textures = textures;
        (made.pass, made.sampler) = (made.render_pass()?, made.sampler()?);
        made.set = made.descriptor_set()?;
        made.pipeline = made.pipeline(made.pixels(), made.layout)?;
        Some(made)
    }

    /// The fragment shader: blending GDI's runs per channel with `dual`.
    fn pixels(&self) -> &'static [u32] {
        #[cfg(windows)]
        if self.dual {
            return &PIXELS_DUAL;
        }
        &PIXELS
    }

    /// The layout of the descriptor set naming the cache and patches (set 0 of every pipeline).
    #[cfg(all(feature = "video", unix))]
    pub(crate) fn set_layout(&self) -> Handle {
        self.set_layout
    }

    /// Memory for something needing `needs`, of the kinds in `kinds` (any kind where none of
    /// those fits).
    pub(crate) fn memory(&self, needs: VkMemoryRequirements, kinds: u32) -> Option<Handle> {
        let fitting = if needs.type_bits & kinds != 0 { needs.type_bits & kinds } else { needs.type_bits };
        let asked = VkMemoryAllocateInfo { kind: 5, size: needs.size, type_index: fitting.trailing_zeros(), ..Default::default() };
        let mut memory = 0;
        // SAFETY: the device is alive; the description is whole.
        (fitting != 0 && unsafe { (self.calls.vkAllocateMemory)(self.device, &asked, null(), &mut memory) } == 0).then_some(memory)
    }

    /// An image `SIDE` square that shaders read and copies fill, and its view.
    fn texture(&self) -> Option<Texture> {
        let (calls, device) = (&self.calls, self.device);
        let usage = USAGE_SAMPLED | USAGE_TRANSFER_DESTINATION;
        let asked =
            VkImageCreateInfo { kind: 14, image_type: 1, format: B8G8R8A8_UNORM, extent: [SIDE as u32, SIDE as u32, 1], mip_levels: 1, array_layers: 1, samples: 1, usage, ..Default::default() };
        let (mut made, mut needs) = (Texture::default(), VkMemoryRequirements::default());
        // SAFETY: the device is alive; each description is whole. What is made is let go of
        // with the pipeline.
        unsafe {
            if (calls.vkCreateImage)(device, &asked, null(), &mut made.image) != 0 {
                return None;
            }
            (calls.vkGetImageMemoryRequirements)(device, made.image, &mut needs);
        }
        let Some(memory) = self.memory(needs, self.local) else {
            // SAFETY: made just now, used by nothing.
            unsafe { (calls.vkDestroyImage)(device, made.image, null()) };
            return None;
        };
        made.memory = memory;
        let seen = VkImageViewCreateInfo { kind: 15, image: made.image, view_type: 1, format: B8G8R8A8_UNORM, range: WHOLE, ..Default::default() };
        // SAFETY: as above.
        let bound = unsafe { (calls.vkBindImageMemory)(device, made.image, memory, 0) == 0 && (calls.vkCreateImageView)(device, &seen, null(), &mut made.view) == 0 };
        if !bound {
            self.let_go_of(made);
            return None;
        }
        Some(made)
    }

    /// Lets go of a texture.
    fn let_go_of(&self, texture: Texture) {
        // SAFETY: the device is done with it; null handles are let be.
        unsafe {
            (self.calls.vkDestroyImageView)(self.device, texture.view, null());
            (self.calls.vkDestroyImage)(self.device, texture.image, null());
            (self.calls.vkFreeMemory)(self.device, texture.memory, null());
        }
    }

    /// The render pass drawing over what an image holds (loaded and stored), in the layout
    /// for drawing before and after.
    fn render_pass(&self) -> Option<Handle> {
        let attachment = VkAttachmentDescription {
            format: B8G8R8A8_UNORM,
            samples: 1,
            load: 0,
            store: 0,
            stencil_load: 2,
            stencil_store: 1,
            initial_layout: LAYOUT_COLOUR,
            final_layout: LAYOUT_COLOUR,
            ..Default::default()
        };
        let colour = VkAttachmentReference { attachment: 0, layout: LAYOUT_COLOUR };
        let subpass = VkSubpassDescription { colour_count: 1, colours: &colour, ..Default::default() };
        let asked = VkRenderPassCreateInfo { kind: 38, attachment_count: 1, attachments: &attachment, subpass_count: 1, subpasses: &subpass, ..Default::default() };
        let mut pass = 0;
        // SAFETY: the device is alive; the description and what it points to live through it.
        (unsafe { (self.calls.vkCreateRenderPass)(self.device, &asked, null(), &mut pass) } == 0).then_some(pass)
    }

    /// The sampler texels are fetched through: nearest, never filtered.
    fn sampler(&self) -> Option<Handle> {
        let asked = VkSamplerCreateInfo { kind: 31, address: [2; 3], ..Default::default() };
        let mut sampler = 0;
        // SAFETY: as above.
        (unsafe { (self.calls.vkCreateSampler)(self.device, &asked, null(), &mut sampler) } == 0).then_some(sampler)
    }

    /// The descriptor set naming the cache and patch images, its layout, pool and the pipeline's
    /// layout made with it.
    fn descriptor_set(&mut self) -> Option<Handle> {
        let (calls, device) = (&self.calls, self.device);
        let binding = |at| VkDescriptorSetLayoutBinding { binding: at, descriptor_type: SAMPLED, count: 1, stages: 0x10, ..Default::default() };
        let bindings = [binding(0), binding(1)];
        let sizes = VkDescriptorPoolSize { descriptor_type: SAMPLED, count: 2 };
        let (mut set, mut layout, mut pool, mut pipeline_layout) = (0, 0, 0, 0);
        // SAFETY: the device is alive; each description is whole and what it points to lives
        // through the call. What is made is held by the pipeline.
        unsafe {
            let described = VkDescriptorSetLayoutCreateInfo { kind: 32, binding_count: 2, bindings: bindings.as_ptr(), ..Default::default() };
            (calls.vkCreateDescriptorSetLayout)(device, &described, null(), &mut layout);
            let pooled = VkDescriptorPoolCreateInfo { kind: 33, max_sets: 1, size_count: 1, sizes: &sizes, ..Default::default() };
            (calls.vkCreateDescriptorPool)(device, &pooled, null(), &mut pool);
            (self.set_layout, self.descriptors) = (layout, pool);
            if layout == 0 || pool == 0 {
                return None;
            }
            let asked = VkDescriptorSetAllocateInfo { kind: 34, pool, count: 1, layouts: &layout, ..Default::default() };
            let laid = VkPipelineLayoutCreateInfo { kind: 30, set_layout_count: 1, set_layouts: &layout, ..Default::default() };
            if (calls.vkAllocateDescriptorSets)(device, &asked, &mut set) != 0 || (calls.vkCreatePipelineLayout)(device, &laid, null(), &mut pipeline_layout) != 0 {
                return None;
            }
        }
        self.layout = pipeline_layout;
        let images = self.textures.map(|texture| VkDescriptorImageInfo { sampler: self.sampler, view: texture.view, layout: LAYOUT_SHADER_READ_ONLY });
        let write = |at: usize| VkWriteDescriptorSet { kind: 35, set, binding: at as u32, count: 1, descriptor_type: SAMPLED, images: &images[at], ..Default::default() };
        let writes = [write(0), write(1)];
        // SAFETY: the set and views are alive; the writes point into `images`, alive here.
        unsafe { (calls.vkUpdateDescriptorSets)(device, 2, writes.as_ptr(), 0, null()) };
        Some(set)
    }

    /// A pipeline of fragment shader `pixels` and `layout`: instanced quads as triangle strips,
    /// nothing culled, blended over what is there (per channel with `dual`), the viewport and
    /// scissor set when drawn.
    pub(crate) fn pipeline(&self, pixels: &[u32], layout: Handle) -> Option<Handle> {
        let (calls, device) = (&self.calls, self.device);
        let module = |code: &[u32]| VkShaderModuleCreateInfo { kind: 16, size: code.len() * 4, code: code.as_ptr(), ..Default::default() };
        let (mut corners, mut shaded, mut pipeline) = (0, 0, 0);
        let binding = VkVertexInputBindingDescription { binding: 0, stride: size_of::<Quad>() as u32, rate: 1 };
        let attributes: [VkVertexInputAttributeDescription; 6] =
            std::array::from_fn(|row| VkVertexInputAttributeDescription { location: row as u32, binding: 0, format: FOUR_FLOATS, offset: row as u32 * 16 });
        let vertex_input = VkPipelineVertexInputStateCreateInfo {
            kind: 19,
            binding_count: 1,
            bindings: (&raw const binding).cast(),
            attribute_count: 6,
            attributes: attributes.as_ptr().cast(),
            ..Default::default()
        };
        let input_assembly = VkPipelineInputAssemblyStateCreateInfo { kind: 20, topology: 4, ..Default::default() };
        let viewport = VkPipelineViewportStateCreateInfo { kind: 22, viewport_count: 1, scissor_count: 1, ..Default::default() };
        let rasterization = VkPipelineRasterizationStateCreateInfo { kind: 23, line_width: 1.0, ..Default::default() };
        let multisample = VkPipelineMultisampleStateCreateInfo { kind: 24, samples: 1, ..Default::default() };
        // One (1); one minus the second colour and alpha (16, 18), or the source alpha (7);
        // added (0); all four written.
        let [colour, alpha] = if self.dual { [16, 18] } else { [7, 7] };
        let blend = VkPipelineColorBlendAttachmentState { enable: 1, source: 1, destination: colour, operation: 0, source_alpha: 1, destination_alpha: alpha, operation_alpha: 0, write_mask: 0xf };
        let colour_blend = VkPipelineColorBlendStateCreateInfo { kind: 26, attachment_count: 1, attachments: &blend, ..Default::default() };
        let states = [0u32, 1];
        let dynamic = VkPipelineDynamicStateCreateInfo { kind: 27, count: 2, states: states.as_ptr(), ..Default::default() };
        // SAFETY: the device is alive; everything each description points to lives through
        // the call; the modules go once the pipeline is made.
        unsafe {
            (calls.vkCreateShaderModule)(device, &module(&CORNERS), null(), &mut corners);
            (calls.vkCreateShaderModule)(device, &module(pixels), null(), &mut shaded);
            let stage = |stage, module| VkPipelineShaderStageCreateInfo { kind: 18, stage, module, name: c"main".as_ptr(), ..Default::default() };
            let stages = [stage(0x1, corners), stage(0x10, shaded)];
            let described = VkGraphicsPipelineCreateInfo {
                kind: 28,
                stage_count: 2,
                stages: stages.as_ptr(),
                vertex_input: &vertex_input,
                input_assembly: &input_assembly,
                viewport: &viewport,
                rasterization: &rasterization,
                multisample: &multisample,
                colour_blend: &colour_blend,
                dynamic: &dynamic,
                layout,
                render_pass: self.pass,
                base_index: -1,
                ..Default::default()
            };
            let made = corners != 0 && shaded != 0 && (calls.vkCreateGraphicsPipelines)(device, 0, 1, &described, null(), &mut pipeline) == 0;
            (calls.vkDestroyShaderModule)(device, corners, null());
            (calls.vkDestroyShaderModule)(device, shaded, null());
            made.then_some(pipeline)
        }
    }

    /// Makes `written` hold at least `bytes`, for `usage`, where it doesn't. (The device is done
    /// with the old one: each submit is waited for.) Says whether it does.
    fn hold(&self, written: &mut Written, bytes: usize, usage: u32) -> bool {
        if bytes <= written.room {
            return true;
        }
        self.unwritten(std::mem::take(written));
        let room = bytes.next_power_of_two().max(65_536);
        let (calls, device, mut needs, mut at) = (&self.calls, self.device, VkMemoryRequirements::default(), null_mut());
        let asked = VkBufferCreateInfo { kind: 12, size: room as u64, usage, ..Default::default() };
        // SAFETY: the device is alive; the buffer is given memory, bound and mapped whole.
        unsafe {
            if (calls.vkCreateBuffer)(device, &asked, null(), &mut written.buffer) != 0 {
                return false;
            }
            (calls.vkGetBufferMemoryRequirements)(device, written.buffer, &mut needs);
        }
        let Some(memory) = self.memory(needs, self.writable) else { return false };
        written.memory = memory;
        // SAFETY: as above.
        let mapped = unsafe { (calls.vkBindBufferMemory)(device, written.buffer, memory, 0) == 0 && (calls.vkMapMemory)(device, memory, 0, u64::MAX, 0, &mut at) == 0 };
        (written.at, written.room) = (at.cast(), if mapped { room } else { 0 });
        mapped
    }

    /// Lets go of a buffer the CPU wrote.
    fn unwritten(&self, written: Written) {
        // SAFETY: the device is done with it; null handles are let be.
        unsafe {
            (self.calls.vkDestroyBuffer)(self.device, written.buffer, null());
            (self.calls.vkFreeMemory)(self.device, written.memory, null());
        }
    }

    /// The framebuffer drawing into `image`, `size` pixels: the last one, or made now.
    fn framebuffer(&mut self, image: Handle, size: [i32; 2]) -> Option<Handle> {
        if (self.target.0, self.target.1) == (image, size) && self.target.3 != 0 {
            return Some(self.target.3);
        }
        self.forget_target();
        let (calls, device, mut view, mut frame) = (&self.calls, self.device, 0, 0);
        let seen = VkImageViewCreateInfo { kind: 15, image, view_type: 1, format: B8G8R8A8_UNORM, range: WHOLE, ..Default::default() };
        // SAFETY: the image is the caller's, alive, and drawn into; the descriptions are whole.
        unsafe {
            if (calls.vkCreateImageView)(device, &seen, null(), &mut view) != 0 {
                return None;
            }
            let asked =
                VkFramebufferCreateInfo { kind: 37, render_pass: self.pass, attachment_count: 1, attachments: &view, width: size[0] as u32, height: size[1] as u32, layers: 1, ..Default::default() };
            if (calls.vkCreateFramebuffer)(device, &asked, null(), &mut frame) != 0 {
                (calls.vkDestroyImageView)(device, view, null());
                return None;
            }
        }
        self.target = (image, size, view, frame);
        Some(frame)
    }

    #[cfg(all(unix, not(target_os = "android")))]
    /// An image `size` pixels a window's pixels are kept and drawn in, in the device's own memory:
    /// copied into, drawn into and copied from. It and its memory; nothing where none is made.
    pub(crate) fn picture(&self, size: [i32; 2]) -> Option<(Handle, Handle)> {
        let (calls, device) = (&self.calls, self.device);
        let usage = USAGE_DRAWN_INTO | USAGE_TRANSFER_SOURCE | USAGE_TRANSFER_DESTINATION;
        let extent = [size[0] as u32, size[1] as u32, 1];
        let asked = VkImageCreateInfo { kind: 14, image_type: 1, format: B8G8R8A8_UNORM, extent, mip_levels: 1, array_layers: 1, samples: 1, usage, ..Default::default() };
        let (mut image, mut needs) = (0, VkMemoryRequirements::default());
        // SAFETY: the device is alive; the description is whole.
        unsafe {
            if (calls.vkCreateImage)(device, &asked, null(), &mut image) != 0 {
                return None;
            }
            (calls.vkGetImageMemoryRequirements)(device, image, &mut needs);
        }
        let memory = self.memory(needs, self.local).unwrap_or(0);
        // SAFETY: as above.
        if memory == 0 || unsafe { (calls.vkBindImageMemory)(device, image, memory, 0) } != 0 {
            self.unpicture((image, memory));
            return None;
        }
        Some((image, memory))
    }

    #[cfg(all(unix, not(target_os = "android")))]
    /// Lets go of an image `picture` made, and its memory. (The device is done with it.)
    pub(crate) fn unpicture(&self, (image, memory): (Handle, Handle)) {
        // SAFETY: as said; null handles are let be.
        unsafe {
            (self.calls.vkDestroyImage)(self.device, image, null());
            (self.calls.vkFreeMemory)(self.device, memory, null());
        }
    }

    #[cfg(all(unix, not(target_os = "android")))]
    /// Records `places` (left, top, right, bottom) copied from image `from` (laid out to be
    /// copied from) into the same places of `to` (to be copied into).
    pub(crate) fn copy_places(&self, commands: Object, from: Handle, to: Handle, places: &[[i32; 4]]) {
        let copy = |&[left, top, right, bottom]: &[i32; 4]| VkImageCopy {
            source_layers: LAYER,
            source_offset: [left, top, 0],
            destination_layers: LAYER,
            destination_offset: [left, top, 0],
            extent: [(right - left) as u32, (bottom - top) as u32, 1],
        };
        for place in places.iter().filter(|place| place[0] < place[2] && place[1] < place[3]) {
            // SAFETY: the commands are being recorded; the place lies in both images (the
            // caller's).
            unsafe { (self.copying.vkCmdCopyImage)(commands, from, LAYOUT_TRANSFER_SOURCE, to, LAYOUT_TRANSFER_DESTINATION, 1, &copy(place)) };
        }
    }

    /// Lets go of the framebuffer of the image drawn into last: called before that image goes.
    /// (The device is done with it.)
    pub(crate) fn forget_target(&mut self) {
        let (_, _, view, frame) = std::mem::take(&mut self.target);
        // SAFETY: as said; null handles are let be.
        unsafe {
            (self.calls.vkDestroyFramebuffer)(self.device, frame, null());
            (self.calls.vkDestroyImageView)(self.device, view, null());
        }
    }

    /// Records into `commands` (being recorded) `list` drawn into `image` (`size` pixels,
    /// B8G8R8A8, made to be drawn into) inside `area` (left, top, right, bottom): its texels put
    /// up first. The image is as `was` says before and in `after` (a layout, read by
    /// copies) after. The CPU's writes are done here: the caller submits, and waits before the
    /// next. Says whether all of it could be recorded.
    #[allow(clippy::too_many_arguments)] // (What drawing into another's image takes.)
    pub(crate) fn record(&mut self, commands: Object, image: Handle, size: [i32; 2], list: &DrawList, area: [i32; 4], was: Was, after: u32) -> bool {
        let mut staging = std::mem::take(&mut self.staging);
        let mut quads = std::mem::take(&mut self.quads);
        let held = self.hold(&mut staging, list.staging.len() * 4, USAGE_COPIED_FROM) && self.hold(&mut quads, list.quads.len().max(1) * size_of::<Quad>(), USAGE_VERTICES);
        (self.staging, self.quads) = (staging, quads);
        let Some(frame) = self.framebuffer(image, size).filter(|_| held) else { return false };
        // SAFETY: both buffers hold that much, mapped; nothing on the device reads them now.
        unsafe {
            std::ptr::copy_nonoverlapping(list.staging.as_ptr(), self.staging.at.cast::<u32>(), list.staging.len());
            std::ptr::copy_nonoverlapping(list.quads.as_ptr(), self.quads.at.cast::<Quad>(), list.quads.len());
        }
        self.put_up(commands, list);
        #[cfg(all(feature = "video", unix))]
        if !self.ready_frames(commands, list) {
            return false;
        }
        let to_draw = VkImageMemoryBarrier { source_access: was.access, destination_access: ACCESS_COLOUR, ..barrier(image, was.layout, LAYOUT_COLOUR, 0, 0) };
        let to_copy = barrier(image, LAYOUT_COLOUR, after, ACCESS_COLOUR, ACCESS_TRANSFER_READ | ACCESS_TRANSFER_WRITE);
        // SAFETY: the commands are being recorded; the image is the caller's.
        unsafe { (self.calls.vkCmdPipelineBarrier)(commands, was.stage, STAGE_COLOUR, 0, 0, null(), 0, null(), 1, &to_draw) };
        self.draw(commands, frame, size, list, area);
        // SAFETY: as above.
        unsafe { (self.calls.vkCmdPipelineBarrier)(commands, STAGE_COLOUR, STAGE_TRANSFER, 0, 0, null(), 0, null(), 1, &to_copy) };
        #[cfg(all(feature = "video", target_os = "android"))]
        if let Some(frames) = &self.frames {
            frames.give_back(commands);
        }
        true
    }

    /// Readies the list's videos' frames for the shaders (see `video_vulkan`): whether they
    /// are, or it has none.
    #[cfg(all(feature = "video", unix))]
    fn ready_frames(&mut self, commands: Object, list: &DrawList) -> bool {
        let Some(mut frames) = self.frames.take() else { return list.frames.is_empty() };
        let ready = frames.ready(self, commands, &list.frames);
        self.frames = Some(frames);
        ready
    }

    /// Records the list's uploads copied into the textures, which are then ready for shaders.
    fn put_up(&mut self, commands: Object, list: &DrawList) {
        self.copies.iter_mut().for_each(Vec::clear);
        for upload in &list.uploads {
            let [x, y, width, height] = upload.at;
            let place =
                VkBufferImageCopy { buffer_offset: upload.from as u64 * 4, row_length: width as u32, layers: LAYER, offset: [x, y, 0], extent: [width as u32, height as u32, 1], ..Default::default() };
            self.copies[upload.texture as usize].push(place);
        }
        let first = !std::mem::replace(&mut self.readied, true);
        for (texture, copies) in self.textures.iter().zip(&self.copies).filter(|(_, copies)| first || !copies.is_empty()) {
            self.fill(commands, texture.image, copies, first);
        }
    }

    /// Records `copies` from the staging buffer into texture `image` (never filled before if
    /// `first`), which is then ready for shaders.
    fn fill(&self, commands: Object, image: Handle, copies: &[VkBufferImageCopy], first: bool) {
        let before = if first { LAYOUT_UNDEFINED } else { LAYOUT_SHADER_READ_ONLY };
        let to_copy = barrier(image, before, LAYOUT_TRANSFER_DESTINATION, ACCESS_SHADER_READ, ACCESS_TRANSFER_WRITE);
        let to_read = barrier(image, LAYOUT_TRANSFER_DESTINATION, LAYOUT_SHADER_READ_ONLY, ACCESS_TRANSFER_WRITE, ACCESS_SHADER_READ);
        // SAFETY: the commands are being recorded; each copy lies in the staging buffer (as the
        // list made it) and in the texture (`Shelves` keeps it there).
        unsafe {
            (self.calls.vkCmdPipelineBarrier)(commands, STAGE_SHADERS, STAGE_TRANSFER, 0, 0, null(), 0, null(), 1, &to_copy);
            if !copies.is_empty() {
                (self.calls.vkCmdCopyBufferToImage)(commands, self.staging.buffer, image, LAYOUT_TRANSFER_DESTINATION, copies.len() as u32, copies.as_ptr());
            }
            (self.calls.vkCmdPipelineBarrier)(commands, STAGE_TRANSFER, STAGE_SHADERS, 0, 0, null(), 0, null(), 1, &to_read);
        }
    }

    /// Binds the pipeline and what it reads into `commands` (in a render pass): the one of the
    /// videos' frames where the part has some.
    fn bind(&self, commands: Object) {
        #[cfg(all(feature = "video", unix))]
        if self.frames.as_ref().is_some_and(|frames| frames.bind(commands, self.set)) {
            return;
        }
        // SAFETY: the commands are being recorded; everything bound is the pipeline's.
        unsafe {
            (self.calls.vkCmdBindPipeline)(commands, 0, self.pipeline);
            (self.calls.vkCmdBindDescriptorSets)(commands, 0, self.layout, 0, 1, &self.set, 0, null());
        }
    }

    /// Records the quads drawn through framebuffer `frame`, `size` pixels, inside `area`.
    fn draw(&self, commands: Object, frame: Handle, size: [i32; 2], list: &DrawList, [left, top, right, bottom]: [i32; 4]) {
        let whole = VkRect2D { offset: [0, 0], extent: size.map(|side| side as u32) };
        let begun = VkRenderPassBeginInfo { kind: 43, render_pass: self.pass, framebuffer: frame, area: whole, ..Default::default() };
        let viewport = VkViewport { x: 0.0, y: 0.0, width: size[0] as f32, height: size[1] as f32, min_depth: 0.0, max_depth: 1.0 };
        let scissor = VkRect2D { offset: [left.max(0), top.max(0)], extent: [(right - left.max(0)).max(0) as u32, (bottom - top.max(0)).max(0) as u32] };
        let (calls, offset) = (&self.calls, 0u64);
        // SAFETY: the commands are being recorded; everything bound is the pipeline's.
        unsafe {
            (calls.vkCmdBeginRenderPass)(commands, &begun, 0);
            if !list.quads.is_empty() {
                self.bind(commands);
                (calls.vkCmdBindVertexBuffers)(commands, 0, 1, &self.quads.buffer, &offset);
                (calls.vkCmdSetViewport)(commands, 0, 1, &viewport);
                (calls.vkCmdSetScissor)(commands, 0, 1, &scissor);
                (calls.vkCmdDraw)(commands, 4, list.quads.len() as u32, 0, 0);
            }
            (calls.vkCmdEndRenderPass)(commands);
        }
    }
}

impl Drop for Pipeline {
    /// Lets go of everything. (The device is done with all of it.)
    fn drop(&mut self) {
        #[cfg(all(feature = "video", unix))]
        drop(self.frames.take());
        self.forget_target();
        [self.staging, self.quads].into_iter().for_each(|written| self.unwritten(written));
        self.textures.into_iter().for_each(|texture| self.let_go_of(texture));
        let (calls, device) = (&self.calls, self.device);
        // SAFETY: each is held once, by this pipeline; null handles are let be.
        unsafe {
            (calls.vkDestroyPipeline)(device, self.pipeline, null());
            (calls.vkDestroyPipelineLayout)(device, self.layout, null());
            (calls.vkDestroyDescriptorPool)(device, self.descriptors, null());
            (calls.vkDestroyDescriptorSetLayout)(device, self.set_layout, null());
            (calls.vkDestroySampler)(device, self.sampler, null());
            (calls.vkDestroyRenderPass)(device, self.pass, null());
        }
    }
}

/// The vertex shader's GLSL: each quad's six rows in, its corner placed from the vertex id;
/// what the pixels need passed on unchanged.
#[allow(dead_code)] // (Read by the test that compiles it.)
pub(crate) const CORNERS_GLSL: &str = r#"#version 450
layout(location = 0) in vec4 place;
layout(location = 1) in vec4 shape;
layout(location = 2) in vec4 more;
layout(location = 3) in vec4 source;
layout(location = 4) in vec4 color;
layout(location = 5) in vec4 kind;
layout(location = 0) flat out vec4 shape_of_quad;
layout(location = 1) flat out vec4 more_of_quad;
layout(location = 2) flat out vec4 source_of_quad;
layout(location = 3) flat out vec4 color_of_quad;
layout(location = 4) flat out float kind_of_quad;
void main() {
    vec2 p = vec2((gl_VertexIndex & 1) != 0 ? place.z : place.x, (gl_VertexIndex & 2) != 0 ? place.w : place.y);
    gl_Position = vec4(p.x / kind.z * 2.0 - 1.0, p.y / kind.w * 2.0 - 1.0, 0.0, 1.0);
    shape_of_quad = shape;
    more_of_quad = more;
    source_of_quad = source;
    color_of_quad = color;
    kind_of_quad = kind.x;
}
"#;

/// The fragment shader's GLSL before `SHADING`: the textures.
#[allow(dead_code)] // (Read by the test that compiles it.)
pub(crate) const TEXTURES_GLSL: &str = r#"#define as_float uintBitsToFloat
layout(set = 0, binding = 0) uniform sampler2D cache;
layout(set = 0, binding = 1) uniform sampler2D patches;
vec4 texel(int which, int x, int y) {
    if (which == 0) {
        return texelFetch(cache, ivec2(x, y), 0);
    }
    return texelFetch(patches, ivec2(x, y), 0);
}
"#;

/// The fragment shader's GLSL after `SHADING`: each pixel what `shade` gives; with `DUAL` also
/// how much of each channel it covers.
#[allow(dead_code)] // (Read by the test that compiles it.)
pub(crate) const PIXELS_GLSL: &str = r#"layout(location = 0) flat in vec4 shape_of_quad;
layout(location = 1) flat in vec4 more_of_quad;
layout(location = 2) flat in vec4 source_of_quad;
layout(location = 3) flat in vec4 color_of_quad;
layout(location = 4) flat in float kind_of_quad;
#ifdef DUAL
layout(location = 0, index = 0) out vec4 drawn_color;
layout(location = 0, index = 1) out vec4 drawn_covers;
#else
layout(location = 0) out vec4 drawn_color;
#endif
void main() {
    vec4 covers = vec4(0.0, 0.0, 0.0, 0.0);
    drawn_color = shade(gl_FragCoord.xy, shape_of_quad, more_of_quad, source_of_quad, color_of_quad, kind_of_quad, covers);
#ifdef DUAL
    drawn_covers = covers;
#endif
}
"#;

/// The fragment shader's whole GLSL, with or without `DUAL`.
#[allow(dead_code)] // (Read by the test that compiles it.)
pub(crate) fn pixels_glsl(dual: bool) -> String {
    let head = if dual { "#version 450\n#define DUAL\n" } else { "#version 450\n" };
    format!("{head}{TEXTURES_GLSL}{SHADING}{PIXELS_GLSL}")
}

