#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use crate::gpu_draw::tests::{Scene, compare};

    #[test]
    fn the_structures_are_laid_out_as_vulkan_lays_them_out() {
        let sizes = [
            (size_of::<VkAttachmentDescription>(), 36),
            (size_of::<VkAttachmentReference>(), 8),
            (size_of::<VkSubpassDescription>(), 72),
            (size_of::<VkRenderPassCreateInfo>(), 64),
            (size_of::<VkFramebufferCreateInfo>(), 64),
            (size_of::<VkRenderPassBeginInfo>(), 64),
            (size_of::<VkSamplerCreateInfo>(), 80),
            (size_of::<VkVertexInputBindingDescription>(), 12),
            (size_of::<VkVertexInputAttributeDescription>(), 16),
            (std::mem::offset_of!(VkRenderPassBeginInfo, area), 32),
            (std::mem::offset_of!(VkSamplerCreateInfo, unnormalized), 76),
        ];
        for (at, (size, wanted)) in sizes.into_iter().enumerate() {
            assert_eq!(size, wanted, "structure {at}");
        }
    }

    /// Whether glslc of shaderc 2026.3 makes other words than `wanted` of `source` (a shader of
    /// `stage`, named `name`); none where there is no such glslc on the path. Where it does, its
    /// words are written as `name`.rs in a folder of the temporary files, which is named.
    pub(crate) fn differs_from_glslc(name: &str, stage: &str, source: &str, wanted: &[u32]) -> Option<bool> {
        let version = std::process::Command::new("glslc").arg("--version").output().map(|said| String::from_utf8_lossy(&said.stdout).into_owned());
        if !version.as_deref().unwrap_or_default().lines().next().unwrap_or_default().contains("2026.3") {
            println!("no glslc of shaderc 2026.3 here: nothing to check ({version:?})");
            return None;
        }
        let folder = std::env::temp_dir().join(format!("taut-draw-spirv-{}", std::process::id()));
        std::fs::create_dir_all(&folder).unwrap();
        let (source_file, code_file) = (folder.join(format!("{name}.{stage}")), folder.join(format!("{name}.spv")));
        std::fs::write(&source_file, source).unwrap();
        let done = std::process::Command::new("glslc").args(["-O", "--target-env=vulkan1.0", "-o"]).arg(&code_file).arg(&source_file).status().expect("glslc");
        assert!(done.success(), "{name} doesn't compile");
        let code: Vec<u32> = std::fs::read(&code_file).unwrap().chunks(4).map(|word| u32::from_le_bytes(word.try_into().unwrap())).collect();
        if code == wanted {
            return Some(false);
        }
        let lines: Vec<String> = code.chunks(16).map(|row| format!("    {},", row.iter().map(|word| format!("{word:#010x}")).collect::<Vec<_>>().join(", "))).collect();
        std::fs::write(folder.join(format!("{name}.rs")), format!("const {name}: [u32; {}] = [\n{}\n];\n", code.len(), lines.join("\n"))).unwrap();
        println!("{name}: glslc's words are in {}", folder.display());
        Some(true)
    }

    /// The SPIR-V is what glslc makes of the GLSL it is built from, where glslc of shaderc
    /// 2026.3 is on the path.
    #[test]
    #[ignore = "needs glslc"]
    fn the_shaders_are_their_source_compiled() {
        let shaders = [("CORNERS", "vert", CORNERS_GLSL.to_string(), &CORNERS[..]), ("PIXELS", "frag", pixels_glsl(false), &PIXELS[..]), ("PIXELS_DUAL", "frag", pixels_glsl(true), &PIXELS_DUAL[..])];
        let differ: Vec<&str> = shaders.iter().filter(|(name, stage, source, wanted)| differs_from_glslc(name, stage, source, wanted) == Some(true)).map(|(name, ..)| *name).collect();
        assert!(differ.is_empty(), "{differ:?} differ from what glslc makes of their source");
    }

    /// A Vulkan device of its own for a test: a CPU device (lavapipe, or SwiftShader where Edge
    /// has it on Windows), with `dualSrcBlend` where it has it.
    pub(crate) struct Bench {
        pub(crate) instance: Object,
        pub(crate) device: Object,
        pub(crate) queue: Object,
        pub(crate) pool: Handle,
        pub(crate) commands: Object,
        pub(crate) fence: Handle,
        pub(crate) memory: VkPhysicalDeviceMemoryProperties,
        pub(crate) dual: bool,
        pub(crate) find: Find,
    }

    functions!(Starting {
        vkCreateInstance: fn(*const VkInstanceCreateInfo, *const c_void, *mut Object) -> i32;
    });
    functions!(Made {
        vkDestroyInstance: fn(Object, *const c_void);
        vkEnumeratePhysicalDevices: fn(Object, *mut u32, *mut Object) -> i32;
        vkGetPhysicalDeviceProperties: fn(Object, *mut VkPhysicalDeviceProperties);
        vkGetPhysicalDeviceFeatures: fn(Object, *mut [u32; 55]);
        vkGetPhysicalDeviceMemoryProperties: fn(Object, *mut VkPhysicalDeviceMemoryProperties);
        vkCreateDevice: fn(Object, *const VkDeviceCreateInfo, *const c_void, *mut Object) -> i32;
        vkDestroyDevice: fn(Object, *const c_void);
        vkGetDeviceQueue: fn(Object, u32, u32, *mut Object);
        vkCreateCommandPool: fn(Object, *const VkCommandPoolCreateInfo, *const c_void, *mut Handle) -> i32;
        vkDestroyCommandPool: fn(Object, Handle, *const c_void);
        vkAllocateCommandBuffers: fn(Object, *const VkCommandBufferAllocateInfo, *mut Object) -> i32;
        vkBeginCommandBuffer: fn(Object, *const VkCommandBufferBeginInfo) -> i32;
        vkEndCommandBuffer: fn(Object) -> i32;
        vkCreateFence: fn(Object, *const VkFenceCreateInfo, *const c_void, *mut Handle) -> i32;
        vkDestroyFence: fn(Object, Handle, *const c_void);
        vkWaitForFences: fn(Object, u32, *const Handle, u32, u64) -> i32;
        vkResetFences: fn(Object, u32, *const Handle) -> i32;
        vkQueueSubmit: fn(Object, u32, *const VkSubmitInfo, Handle) -> i32;
        vkCmdCopyImageToBuffer: fn(Object, Handle, u32, Handle, u32, *const VkBufferImageCopy);
        vkDeviceWaitIdle: fn(Object) -> i32;
    });

    /// The test's way to Vulkan: SwiftShader on Windows (a loader in an elevated program takes
    /// no driver from its environment), the system's loader elsewhere.
    fn finder() -> Option<Find> {
        #[cfg(windows)]
        return crate::gpu_vulkan_windows::tests::swiftshader();
        #[cfg(not(windows))]
        loader()
    }

    impl Bench {
        pub(crate) fn new() -> Option<(Bench, Made)> {
            let find = finder()?;
            let global = Starting::load(&mut |name| unsafe { find(null_mut(), name.as_ptr()) }).ok()?;
            let application = VkApplicationInfo { name: c"taut".as_ptr(), api_version: 1 << 22, ..Default::default() };
            let asked = VkInstanceCreateInfo { kind: 1, application: &application, ..Default::default() };
            let mut instance = null_mut();
            if unsafe { (global.vkCreateInstance)(&asked, null(), &mut instance) } != 0 {
                return None;
            }
            let made = Made::load(&mut |name| unsafe { find(instance, name.as_ptr()) }).ok()?;
            let (mut count, mut physical) = (8, [null_mut(); 8]);
            unsafe { (made.vkEnumeratePhysicalDevices)(instance, &mut count, physical.as_mut_ptr()) };
            let cpu = physical[..count as usize].iter().copied().find(|physical| {
                let mut properties = VkPhysicalDeviceProperties::default();
                unsafe { (made.vkGetPhysicalDeviceProperties)(*physical, &mut properties) };
                properties.device_type == 4
            })?;
            let (mut features, mut memory) = ([0u32; 55], VkPhysicalDeviceMemoryProperties::default());
            unsafe {
                (made.vkGetPhysicalDeviceFeatures)(cpu, &mut features);
                (made.vkGetPhysicalDeviceMemoryProperties)(cpu, &mut memory);
            }
            let dual = features[7] != 0;
            let mut wanted = [0u32; 55];
            wanted[7] = dual as u32;
            let priority = 1.0f32;
            let queue = VkDeviceQueueCreateInfo { kind: 2, family: 0, count: 1, priorities: &priority, ..Default::default() };
            // (Swap chains too: the HDR pass leaves an image ready to present.)
            let swap_chains = c"VK_KHR_swapchain".as_ptr();
            let asked = VkDeviceCreateInfo { kind: 3, queue_count: 1, queues: &queue, extension_count: 1, extensions: &swap_chains, features: wanted.as_ptr().cast(), ..Default::default() };
            let mut device = null_mut();
            assert_eq!(unsafe { (made.vkCreateDevice)(cpu, &asked, null(), &mut device) }, 0);
            let bench = Bench::on(&made, find, instance, device, memory, dual);
            Some((bench, made))
        }

        /// A bench on `device` (made of `instance`, whose functions `find` finds; its memory
        /// `memory`, blending per channel where `dual`): its queue 0 of family 0, a command
        /// buffer and a fence.
        pub(crate) fn on(made: &Made, find: Find, instance: Object, device: Object, memory: VkPhysicalDeviceMemoryProperties, dual: bool) -> Bench {
            let mut bench = Bench { instance, device, queue: null_mut(), pool: 0, commands: null_mut(), fence: 0, memory, dual, find };
            unsafe {
                (made.vkGetDeviceQueue)(device, 0, 0, &mut bench.queue);
                (made.vkCreateCommandPool)(device, &VkCommandPoolCreateInfo { kind: 39, flags: 0x2, ..Default::default() }, null(), &mut bench.pool);
                (made.vkAllocateCommandBuffers)(device, &VkCommandBufferAllocateInfo { kind: 40, pool: bench.pool, count: 1, ..Default::default() }, &mut bench.commands);
                (made.vkCreateFence)(device, &VkFenceCreateInfo { kind: 8, ..Default::default() }, null(), &mut bench.fence);
            }
            bench
        }

        /// The pipeline drawing on this device.
        pub(crate) fn pipeline(&self) -> Box<Pipeline> {
            let (find, instance) = (self.find, self.instance);
            Pipeline::new(&mut |name| unsafe { find(instance, name.as_ptr()) }, self.device, &self.memory, self.dual).expect("the pipeline is made")
        }

        /// Draws `list` into a new image `size` pixels, first filled with `under`, and reads
        /// it back, row after row.
        pub(crate) fn drawn(&self, made: &Made, pipeline: &mut Pipeline, list: &DrawList, size: [i32; 2], under: &[u32]) -> Vec<u32> {
            let draws = Calls::load(&mut |name| unsafe { (self.find)(self.instance, name.as_ptr()) }).unwrap();
            let usage = USAGE_DRAWN_INTO | USAGE_TRANSFER_SOURCE | USAGE_TRANSFER_DESTINATION;
            let asked = VkImageCreateInfo {
                kind: 14,
                image_type: 1,
                format: B8G8R8A8_UNORM,
                extent: [size[0] as u32, size[1] as u32, 1],
                mip_levels: 1,
                array_layers: 1,
                samples: 1,
                usage,
                ..Default::default()
            };
            let (mut image, mut needs) = (0, VkMemoryRequirements::default());
            unsafe {
                assert_eq!((draws.vkCreateImage)(self.device, &asked, null(), &mut image), 0);
                (draws.vkGetImageMemoryRequirements)(self.device, image, &mut needs);
            }
            let memory = pipeline.memory(needs, pipeline.local).unwrap();
            unsafe { (draws.vkBindImageMemory)(self.device, image, memory, 0) };
            let bytes = (size[0] * size[1] * 4) as usize;
            let mut buffer = Written::default();
            assert!(pipeline.hold(&mut buffer, bytes, USAGE_COPIED_FROM | USAGE_TRANSFER_DESTINATION));
            unsafe { std::ptr::copy_nonoverlapping(under.as_ptr(), buffer.at.cast::<u32>(), under.len()) };
            let whole = VkBufferImageCopy { row_length: size[0] as u32, layers: LAYER, extent: [size[0] as u32, size[1] as u32, 1], ..Default::default() };
            unsafe {
                (made.vkBeginCommandBuffer)(self.commands, &VkCommandBufferBeginInfo { kind: 42, flags: 1, ..Default::default() });
                let fill = barrier(image, LAYOUT_UNDEFINED, LAYOUT_TRANSFER_DESTINATION, 0, ACCESS_TRANSFER_WRITE);
                (draws.vkCmdPipelineBarrier)(self.commands, STAGE_TOP, STAGE_TRANSFER, 0, 0, null(), 0, null(), 1, &fill);
                (draws.vkCmdCopyBufferToImage)(self.commands, buffer.buffer, image, LAYOUT_TRANSFER_DESTINATION, 1, &whole);
            }
            let was = Was { layout: LAYOUT_TRANSFER_DESTINATION, access: ACCESS_TRANSFER_WRITE, stage: STAGE_TRANSFER };
            assert!(pipeline.record(self.commands, image, size, list, [0, 0, size[0], size[1]], was, 6));
            unsafe {
                (made.vkCmdCopyImageToBuffer)(self.commands, image, 6, buffer.buffer, 1, &whole);
                assert_eq!((made.vkEndCommandBuffer)(self.commands), 0);
                let submit = VkSubmitInfo { kind: 4, buffer_count: 1, buffers: &self.commands, ..Default::default() };
                assert_eq!((made.vkQueueSubmit)(self.queue, 1, &submit, self.fence), 0);
                assert_eq!((made.vkWaitForFences)(self.device, 1, &self.fence, 1, 10_000_000_000), 0);
                (made.vkResetFences)(self.device, 1, &self.fence);
            }
            let pixels = unsafe { std::slice::from_raw_parts(buffer.at.cast::<u32>(), (size[0] * size[1]) as usize) }.to_vec();
            pipeline.forget_target();
            pipeline.unwritten(buffer);
            unsafe {
                (draws.vkDestroyImage)(self.device, image, null());
                (draws.vkFreeMemory)(self.device, memory, null());
            }
            pixels
        }

        pub(crate) fn finish(self, made: Made) {
            unsafe {
                (made.vkDeviceWaitIdle)(self.device);
                (made.vkDestroyFence)(self.device, self.fence, null());
                (made.vkDestroyCommandPool)(self.device, self.pool, null());
                (made.vkDestroyDevice)(self.device, null());
                (made.vkDestroyInstance)(self.instance, null());
            }
        }
    }

    #[test]
    fn vulkan_draws_every_kind_of_thing_as_the_cpu_does() {
        let Some((bench, made)) = Bench::new() else { return println!("no Vulkan CPU device here: nothing to compare") };
        let mut pipeline = bench.pipeline();
        for scale in [1.0, 1.5, 2.0] {
            let (mut scene, mut list) = (Scene::new(scale), DrawList::default());
            scene.record(&mut list);
            assert!(!list.failed, "all of it on the GPU");
            let gpu = bench.drawn(&made, &mut pipeline, &list, scene.size, &scene.under);
            compare(&scene, &gpu, &format!("Vulkan (dual {}) at {scale}", bench.dual));
            // Again: the glyphs and runs are kept, and only this part's patches go up.
            scene.record(&mut list);
            let again = bench.drawn(&made, &mut pipeline, &list, scene.size, &scene.under);
            compare(&scene, &again, &format!("Vulkan again at {scale}"));
        }
        drop(pipeline);
        bench.finish(made);
    }
}
